import { useState, useEffect } from 'react'; // Fixed: Added useEffect import
import { Link } from 'react-router-dom';
import PropertyCard from '../components/common/PropertyCard';

function Buy() {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  // Fixed: Added missing filters state
  const [filters, setFilters] = useState({
    location: 'All Locations',
    propertyType: 'All Types',
    minPrice: '',
    maxPrice: ''
  });
  
  // Fixed: Added missing sortBy state
  const [sortBy, setSortBy] = useState('newest');

  // Fetch properties from API
  useEffect(() => {
    const fetchProperties = async () => {
      try {
        const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:8000/api/';
        const response = await fetch(`${apiUrl}properties`);
        
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }
        
        const data = await response.json();
        setProperties(data || []);
      } catch (err) {
        console.error('Fetch error:', err);
        setError(err.message || 'Could not load properties. Please try again.');
        setProperties([]);
      } finally {
        setLoading(false);
      }
    };
    
    fetchProperties();
  }, []);

  // Get all buy properties
  const buyProperties = properties.filter(p => p.property_type === 'sale');

  // Apply filters and sorting
  const getFilteredAndSortedProperties = () => {
    let filtered = [...buyProperties];

    // Apply location filter
    if (filters.location !== 'All Locations') {
      filtered = filtered.filter(p => 
        p.location?.toLowerCase() === filters.location.toLowerCase()
      );
    }

    // Apply property type filter
    if (filters.propertyType !== 'All Types') {
      filtered = filtered.filter(p => 
        p.propertyType?.toLowerCase() === filters.propertyType.toLowerCase()
      );
    }

    // Apply price range filter
    if (filters.minPrice) {
      filtered = filtered.filter(p => p.price >= parseInt(filters.minPrice));
    }
    if (filters.maxPrice) {
      filtered = filtered.filter(p => p.price <= parseInt(filters.maxPrice));
    }

    // Apply sorting
    switch(sortBy) {
      case 'price-low-high':
        filtered.sort((a, b) => a.price - b.price);
        break;
      case 'price-high-low':
        filtered.sort((a, b) => b.price - a.price);
        break;
      case 'newest':
      default:
        filtered.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
        break;
    }

    return filtered;
  };

  const finalFilteredProperties = getFilteredAndSortedProperties();

  // Handle filter changes
  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  // Handle sort change
  const handleSortChange = (e) => {
    setSortBy(e.target.value);
  };

  // Reset all filters
  const handleResetFilters = () => {
    setFilters({
      location: 'All Locations',
      propertyType: 'All Types',
      minPrice: '',
      maxPrice: ''
    });
    setSortBy('newest');
  };

  // Show loading state
  if (loading) {
    return (
      <div className="min-h-screen bg-bg-soft flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto"></div>
          <p className="mt-4 text-text-muted">Loading properties...</p>
        </div>
      </div>
    );
  }

  // Show error state
  if (error) {
    return (
      <div className="min-h-screen bg-bg-soft flex items-center justify-center">
        <div className="text-center">
          <p className="text-red-600 mb-4">{error}</p>
          <button 
            onClick={() => window.location.reload()} 
            className="btn-primary"
          >
            Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-bg-soft py-12">
      <div className="max-w-7xl mx-auto px-4">
        <h1 className="text-5xl font-bold text-text-primary text-center mb-4">
          Buy Properties in Nigeria
        </h1>
        <p className="text-xl text-text-muted text-center mb-12">
          Find your dream home to own — luxury apartments, houses, and land
        </p>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          {/* Filters Sidebar */}
          <div className="lg:col-span-1">
            <div className="bg-white rounded-xl shadow-card p-6 sticky top-24">
              <h3 className="text-xl font-bold text-text-primary mb-6">Filters</h3>
              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-text-primary mb-2">Location</label>
                  <select 
                    name="location"
                    value={filters.location}
                    onChange={handleFilterChange}
                    className="w-full px-4 py-3 border border-border-light rounded-lg focus:ring-2 focus:ring-primary focus:outline-none"
                  >
                    <option>All Locations</option>
                    <option>Lagos</option>
                    <option>Abuja</option>
                    <option>Port Harcourt</option>
                    <option>Ibadan</option>
                    <option>Kano</option>
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium text-text-primary mb-2">Property Type</label>
                  <select 
                    name="propertyType"
                    value={filters.propertyType}
                    onChange={handleFilterChange}
                    className="w-full px-4 py-3 border border-border-light rounded-lg focus:ring-2 focus:ring-primary focus:outline-none"
                  >
                    <option>All Types</option>
                    <option>House</option>
                    <option>Apartment</option>
                    <option>Land</option>
                    <option>Duplex</option>
                    <option>Mansion</option>
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium text-text-primary mb-2">Price Range (₦)</label>
                  <input 
                    type="number" 
                    name="minPrice"
                    value={filters.minPrice}
                    onChange={handleFilterChange}
                    placeholder="Min Price" 
                    className="w-full px-4 py-3 border border-border-light rounded-lg mb-2 focus:ring-2 focus:ring-primary focus:outline-none" 
                  />
                  <input 
                    type="number" 
                    name="maxPrice"
                    value={filters.maxPrice}
                    onChange={handleFilterChange}
                    placeholder="Max Price" 
                    className="w-full px-4 py-3 border border-border-light rounded-lg focus:ring-2 focus:ring-primary focus:outline-none" 
                  />
                </div>
                
                <div className="space-y-3">
                  <button 
                    onClick={handleResetFilters}
                    className="w-full btn-primary"
                  >
                    Apply Filters
                  </button>
                  <button 
                    onClick={handleResetFilters}
                    className="w-full px-4 py-3 border border-border-light rounded-lg text-text-primary hover:bg-gray-50 transition-colors"
                  >
                    Reset Filters
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* Properties Grid */}
          <div className="lg:col-span-3">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
              <p className="text-text-muted">
                {finalFilteredProperties.length} property{finalFilteredProperties.length !== 1 ? 's' : ''} found
              </p>
              <select 
                value={sortBy}
                onChange={handleSortChange}
                className="px-4 py-2 border border-border-light rounded-lg focus:ring-2 focus:ring-primary focus:outline-none"
              >
                <option value="newest">Sort by: Newest</option>
                <option value="price-low-high">Price: Low to High</option>
                <option value="price-high-low">Price: High to Low</option>
              </select>
            </div>

            {finalFilteredProperties.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {finalFilteredProperties.map((property) => (
                  <PropertyCard key={property.id} property={property} />
                ))}
              </div>
            ) : (
              <div className="text-center py-20">
                <div className="text-6xl mb-4">🏠</div>
                <p className="text-text-muted text-lg mb-4">No properties found matching your criteria.</p>
                <button 
                  onClick={handleResetFilters}
                  className="btn-primary inline-block"
                >
                  Clear Filters
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default Buy;